fn scan(s:[*]const u8,lo:usize,hi:usize,h:*u64)void{var depth:usize=0;var begin:usize=0;for(lo..hi)|i|{if(s[i]=='<'){if(depth==0)begin=i;depth+=1;}else if(s[i]=='>'){depth-=1;if(depth==0){for(begin..i+1)|j|h.*=(h.**257+s[j]+1)%1000000007;scan(s,begin+1,i,h);}}}}
export fn parse_nested_brackets(v:[*c]const i64,n:usize)i64{if(v==null or n<1 or n>129 or v[0]<0 or v[0]>128 or n!=@as(usize,@intCast(v[0]))+1)return -1;const len:usize=@intCast(v[0]);var s=[_]u8{0}**128;var depth:usize=0;for(0..len)|i|{const x=v[i+1];if(x<0 or x>127)return -1;s[i]=@intCast(x);if(s[i]=='<')depth+=1 else if(s[i]=='>'){if(depth==0)return -1;depth-=1;}}if(depth!=0)return -1;var h:u64=0;scan(&s,0,len,&h);return @intCast(h);}
